begin
insert into public.buildings(building_name) values ('重調回帰試験（ロールバック）') returning building_id into b;
insert into public.units(building_id,house_number,management_fee) values(b,'__important_report_regression__',777) returning unit_id into u;
p:=jsonb_set(p,'{identity,unit_id}',to_jsonb(u::text));
a:=public.save_important_report(p);
