changed:=jsonb_set(changed,'{raw_json,fields,management_fee,source_text}','"月額管理費13,500円"'::jsonb);
changed:=jsonb_set(changed,'{import_key}',to_jsonb(repeat('b',64)));
r:=public.save_important_report(changed);
assert r->>'diffs_created'='1';
select management_fee into fee from public.units where unit_id=u;
assert fee=777;
select count(*) into cnt from public.value_diffs where new_version_id=(r->>'document_version_id')::uuid and review_status='unreviewed' and field_code='management_fee';
