got:=public.get_approved_important_report(jsonb_build_object('document_version_id',a->>'document_version_id'));
assert got->'fields'->'management_fee'->>'value'='12000';
got:=public.get_approved_important_report(jsonb_build_object('document_version_id',r->>'document_version_id'));
assert got->'fields'='{}'::jsonb;
r:=public.save_important_report(changed);assert r->>'reused'='true' and r->>'diffs_created'='0';
end $test$;
